import { jsx as _jsx } from "react/jsx-runtime";
import { describe, it, expect, vi, beforeEach } from "vitest";
import { screen, render, waitFor, fireEvent } from "@testing-library/react";
import { userEvent } from "@testing-library/user-event";
import "@testing-library/jest-dom/vitest";
import { AIFeedbackPopper } from "../AIFeedbackPopper";
import { RDSThemeProvider, THEME_MODES } from "../../../rdsThemeProvider";
import { CallistoThemeMap } from "../../../callistoTheme";
const mockOnSubmit = vi.fn();
const mockOnClose = vi.fn();
const renderWithTheme = (ui) => {
    return render(_jsx(RDSThemeProvider, { themeMap: CallistoThemeMap, themeMode: THEME_MODES.LIGHT, children: ui }));
};
describe("AIFeedbackPopper", () => {
    beforeEach(() => {
        vi.resetAllMocks();
    });
    it("should not render when anchorEl is null", () => {
        renderWithTheme(_jsx(AIFeedbackPopper, { anchorEl: null, charLimit: 500, onClose: mockOnClose, onSubmit: mockOnSubmit, result: "positive" }));
        expect(screen.queryByText(/give feedback/i)).not.toBeInTheDocument();
    });
    it("should render when anchorEl is provided", () => {
        const anchorEl = document.createElement("button");
        renderWithTheme(_jsx(AIFeedbackPopper, { anchorEl: anchorEl, charLimit: 500, onClose: mockOnClose, onSubmit: mockOnSubmit, result: "positive" }));
        expect(screen.getByText(/give feedback/i)).toBeInTheDocument();
    });
    it("should call onClose when close button is clicked", async () => {
        const user = userEvent.setup();
        const anchorEl = document.createElement("button");
        renderWithTheme(_jsx(AIFeedbackPopper, { anchorEl: anchorEl, charLimit: 500, onClose: mockOnClose, onSubmit: mockOnSubmit, result: "positive" }));
        await user.click(screen.getByRole("button", { name: /close/i }));
        expect(mockOnClose).toHaveBeenCalled();
    });
    it("should call onClose when cancel button is clicked", async () => {
        const user = userEvent.setup();
        const anchorEl = document.createElement("button");
        renderWithTheme(_jsx(AIFeedbackPopper, { anchorEl: anchorEl, charLimit: 500, onClose: mockOnClose, onSubmit: mockOnSubmit, result: "positive" }));
        await user.click(screen.getByRole("button", { name: /cancel/i }));
        expect(mockOnClose).toHaveBeenCalled();
    });
    it("should allow multiple checkbox selections", async () => {
        const user = userEvent.setup();
        const anchorEl = document.createElement("button");
        renderWithTheme(_jsx(AIFeedbackPopper, { anchorEl: anchorEl, charLimit: 500, onClose: mockOnClose, onSubmit: mockOnSubmit, result: "positive" }));
        const checkbox1 = screen.getByLabelText(/helpful context/i);
        const checkbox2 = screen.getByLabelText(/agree with conclusion/i);
        await user.click(checkbox1);
        await user.click(checkbox2);
        expect(checkbox1).toBeChecked();
        expect(checkbox2).toBeChecked();
    });
    it("should validate comment field with valid characters", async () => {
        const user = userEvent.setup();
        const anchorEl = document.createElement("button");
        renderWithTheme(_jsx(AIFeedbackPopper, { anchorEl: anchorEl, charLimit: 500, onClose: mockOnClose, onSubmit: mockOnSubmit, result: "positive" }));
        const textarea = screen.getByPlaceholderText(/additional comments/i);
        await user.type(textarea, "Valid text\nwith numbers 123 and symbols !@#$");
        expect(textarea).toHaveValue("Valid text\nwith numbers 123 and symbols !@#$");
    });
    it("should submit with selected options and comment", async () => {
        const user = userEvent.setup();
        const anchorEl = document.createElement("button");
        mockOnSubmit.mockImplementation(() => new Promise((resolve) => setTimeout(resolve, 100)));
        renderWithTheme(_jsx(AIFeedbackPopper, { anchorEl: anchorEl, charLimit: 500, onClose: mockOnClose, onSubmit: mockOnSubmit, result: "positive" }));
        await user.click(screen.getByLabelText(/helpful context/i));
        await user.click(screen.getByLabelText(/agree with conclusion/i));
        await user.type(screen.getByPlaceholderText(/additional comments/i), "Great work!");
        const submitButton = screen.getByRole("button", { name: /^submit$/i });
        fireEvent.click(submitButton);
        expect(submitButton).toBeDisabled();
        await waitFor(() => {
            expect(mockOnSubmit).toHaveBeenCalledWith("positive", ["helpfulContext", "agreeWithConclusion"], "Great work!");
        });
    });
    it("should call onClose after successful submission in the next tick, not synchronously", async () => {
        const user = userEvent.setup();
        const anchorEl = document.createElement("button");
        let resolveSubmit;
        mockOnSubmit.mockImplementation(() => new Promise((resolve) => {
            resolveSubmit = resolve;
        }));
        renderWithTheme(_jsx(AIFeedbackPopper, { anchorEl: anchorEl, charLimit: 500, onClose: mockOnClose, onSubmit: mockOnSubmit, result: "positive" }));
        await user.click(screen.getByRole("button", { name: /^submit$/i }));
        // onSubmit is in-flight — onClose must not have been called yet
        expect(mockOnClose).not.toHaveBeenCalled();
        // Resolve the submission — onClose should fire after the next render cycle
        resolveSubmit();
        await waitFor(() => {
            expect(mockOnClose).toHaveBeenCalledTimes(1);
        });
    });
    it("should not call onClose even if submission fails", async () => {
        const user = userEvent.setup();
        const anchorEl = document.createElement("button");
        // Mock a failing submission that catches its own error
        mockOnSubmit.mockImplementation(async () => {
            try {
                throw new Error("Submission failed");
            }
            catch {
                // Simulate error being handled by parent component
                return undefined;
            }
        });
        renderWithTheme(_jsx(AIFeedbackPopper, { anchorEl: anchorEl, charLimit: 500, onClose: mockOnClose, onSubmit: mockOnSubmit, result: "positive" }));
        await user.click(screen.getByRole("button", { name: /^submit$/i }));
        await waitFor(() => {
            expect(mockOnSubmit).toHaveBeenCalled();
        });
        // When submission completes (even with handled error), onClose should be called
        await waitFor(() => {
            expect(mockOnClose).toHaveBeenCalled();
        });
    });
    it("should allow submission with empty comment", async () => {
        const user = userEvent.setup();
        const anchorEl = document.createElement("button");
        mockOnSubmit.mockResolvedValue(undefined);
        renderWithTheme(_jsx(AIFeedbackPopper, { anchorEl: anchorEl, charLimit: 500, onClose: mockOnClose, onSubmit: mockOnSubmit, result: "positive" }));
        const textarea = screen.getByPlaceholderText(/additional comments/i);
        expect(textarea).toHaveAttribute("aria-invalid", "false");
        await user.click(screen.getByRole("button", { name: /^submit$/i }));
        await waitFor(() => {
            expect(mockOnSubmit).toHaveBeenCalledWith("positive", [], "");
            expect(mockOnClose).toHaveBeenCalled();
        });
    });
    it("should show error when comment exceeds character limit", async () => {
        const user = userEvent.setup();
        const anchorEl = document.createElement("button");
        renderWithTheme(_jsx(AIFeedbackPopper, { anchorEl: anchorEl, charLimit: 10, onClose: mockOnClose, onSubmit: mockOnSubmit, result: "positive" }));
        const textarea = screen.getByPlaceholderText(/additional comments/i);
        await user.type(textarea, "This comment is too long");
        expect(textarea).toHaveAttribute("aria-invalid", "true");
    });
    it("should not submit when comment has error and should focus textarea", async () => {
        const user = userEvent.setup();
        const anchorEl = document.createElement("button");
        renderWithTheme(_jsx(AIFeedbackPopper, { anchorEl: anchorEl, charLimit: 10, onClose: mockOnClose, onSubmit: mockOnSubmit, result: "positive" }));
        const textarea = screen.getByPlaceholderText(/additional comments/i);
        await user.type(textarea, "This is way too long");
        await user.click(screen.getByRole("button", { name: /^submit$/i }));
        expect(mockOnSubmit).not.toHaveBeenCalled();
        expect(textarea).toHaveFocus();
    });
    it("should display loading state during submission", async () => {
        const user = userEvent.setup();
        const anchorEl = document.createElement("button");
        mockOnSubmit.mockImplementation(() => new Promise((resolve) => setTimeout(resolve, 1000)));
        renderWithTheme(_jsx(AIFeedbackPopper, { anchorEl: anchorEl, charLimit: 500, onClose: mockOnClose, onSubmit: mockOnSubmit, result: "positive" }));
        await user.click(screen.getByRole("button", { name: /^submit$/i }));
        expect(screen.getByText(/submitting/i)).toBeInTheDocument();
        expect(screen.getByRole("progressbar")).toBeInTheDocument();
        await waitFor(() => {
            expect(mockOnClose).toHaveBeenCalled();
        });
    });
});
